public interface IRateLimiter
{
    bool TryAcquire(int permits = 1);
    ValueTask WaitAsync(int permits, CancellationToken ct);
}

public sealed class SlidingWindowRateLimiter : IRateLimiter
{
    private readonly object _sync = new();
    private readonly int _limit;
    private readonly TimeSpan _window;
    private readonly TimeProvider _time;
    private readonly Queue<DateTimeOffset> _timestamps = new();

    public SlidingWindowRateLimiter(int limit, TimeSpan window, TimeProvider? time = null)
    {
        if (limit <= 0) throw new ArgumentOutOfRangeException(nameof(limit));
        _limit = limit;
        _window = window;
        _time = time ?? TimeProvider.System;
    }

    public bool TryAcquire(int permits = 1)
    {
        ValidatePermits(permits);
        lock (_sync)
        {
            Prune();
            if (_timestamps.Count + permits > _limit) return false;
            var now = _time.GetUtcNow();
            for (var i = 0; i < permits; i++) _timestamps.Enqueue(now);
            return true;
        }
    }

    public async ValueTask WaitAsync(int permits, CancellationToken ct)
    {
        ValidatePermits(permits);
        while (!TryAcquire(permits))
        {
            DateTimeOffset wakeAt;
            lock (_sync)
            {
                wakeAt = _timestamps.Count > 0
                    ? _timestamps.Peek().Add(_window)
                    : _time.GetUtcNow();
            }
            var delay = wakeAt - _time.GetUtcNow();
            if (delay > TimeSpan.Zero)
                await Task.Delay(delay, _time, ct).ConfigureAwait(false);
            else
                await Task.Yield();
        }
    }

    private void ValidatePermits(int permits)
    {
        if (permits <= 0 || permits > _limit)
            throw new ArgumentOutOfRangeException(nameof(permits));
    }

    private void Prune()
    {
        var cutoff = _time.GetUtcNow() - _window;
        while (_timestamps.Count > 0 && _timestamps.Peek() < cutoff)
            _timestamps.Dequeue();
    }
}
